package br.com.exotermo.hermes.app.application;
import static org.junit.jupiter.api.Assertions.*; import br.com.exotermo.hermes.app.domain.*; import java.util.*; import org.junit.jupiter.api.Test;
class HermesCoreFlowTest { @Test void createsAndExecutesATaskThroughTheGeneralAgent() { Map<TaskId,Task> taskData=new HashMap<>(); List<Execution> runs=new ArrayList<>(); TaskRepository tasks=new TaskRepository(){public Task save(Task t){taskData.put(t.id(),t);return t;}public Optional<Task> findById(TaskId id){return Optional.ofNullable(taskData.get(id));}}; ExecutionRepository executions=e->{runs.add(e);return e;}; LlmClient fake=(model,messages,taskId,agentId)->"[mock] " + messages.get(1).content(); var create=new CreateTaskUseCase(tasks); var execute=new ExecuteTaskUseCase(tasks,executions,new HermesOrchestrator(new AgentExecutor(fake))); Task task=create.create("summarize this"); Execution result=execute.execute(task.id()); assertEquals(TaskStatus.COMPLETED,tasks.findById(task.id()).orElseThrow().status());assertEquals(ExecutionStatus.COMPLETED,result.status());assertTrue(result.result().startsWith("[mock]")); } }
